const DB_NAME="chuneside-offline-test",DB_VERSION=2;
const GENRES=["All genres","Soca","Calypso","Reggae","Dancehall","Hip-Hop","Rap","R&B","Gospel","Other"];
const palette=[["#ff4d00","#ffe600"],["#03a678","#071d44"],["#8b3dff","#ff2fa6"],["#dfff00","#00a57d"],["#00c2ff","#0063cc"],["#ff1967","#401028"]];
const THEMES={original:{primary:"#dfff00",secondary:"#7d2cff",accent:"#ff4279"},carnival:{primary:"#ff2f92",secondary:"#ff7a00",accent:"#009dff"},ocean:{primary:"#00e5ff",secondary:"#006dff",accent:"#8d5cff"},christmas:{primary:"#50ff88",secondary:"#d92d47",accent:"#ffd45c"},sunset:{primary:"#ff8a00",secondary:"#ff315f",accent:"#ffd35a"},bright:{primary:"#fff200",secondary:"#00d9ff",accent:"#ff33ad",bg:"#11131a",panel:"#1c1f29"},midnight:{primary:"#9b79ff",secondary:"#252c5c",accent:"#00d0c6",bg:"#02030a",panel:"#090c18"}};
const FAN_RANKS=[{name:"New Listener",icon:"◉",min:0},{name:"Vibe Scout",icon:"✦",min:100},{name:"Sound Supporter",icon:"◆",min:300},{name:"Chune Champion",icon:"★",min:700},{name:"Island Tastemaker",icon:"♛",min:1500},{name:"ChuneSide Legend",icon:"♬",min:3000}];
const MILESTONES={views:[1,50,100,500,1000],likes:[10,25,50,100],follows:[5,20,50,100]};
const DEFAULT_SUBMISSION={emails:"chuneside@gmail.com",audio:"MP3 · high-quality stereo",video:"MP4 · 1080p preferred",artwork:"JPG or PNG · 3000 × 3000 pixels · square",artistPicture:"JPG or PNG · clear high-resolution portrait"};
const state={db:null,tracks:[],profiles:[],likes:[],follows:[],artists:[],settings:[],activeProfile:localStorage.getItem("chuneside-active-profile")||"guest",filter:"all",genre:"All genres",query:"",period:"monthly",sort:"newest",chartGenre:"All genres"};
const objectUrls=new Map(),$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let heroTimer=null,bannerTimer=null,activityTimer=null,lastActivityTick=Date.now();
const esc=v=>String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[c]);

function openDb(){return new Promise((resolve,reject)=>{const request=indexedDB.open(DB_NAME,DB_VERSION);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains("tracks"))db.createObjectStore("tracks",{keyPath:"id",autoIncrement:true});if(!db.objectStoreNames.contains("profiles"))db.createObjectStore("profiles",{keyPath:"id"});if(!db.objectStoreNames.contains("likes"))db.createObjectStore("likes",{keyPath:"key"});if(!db.objectStoreNames.contains("follows"))db.createObjectStore("follows",{keyPath:"key"});if(!db.objectStoreNames.contains("artists"))db.createObjectStore("artists",{keyPath:"id"});if(!db.objectStoreNames.contains("settings"))db.createObjectStore("settings",{keyPath:"key"})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
function result(request){return new Promise((resolve,reject)=>{request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
function store(name,mode="readonly"){return state.db.transaction(name,mode).objectStore(name)}
function all(name){return result(store(name).getAll())}function put(name,value){return result(store(name,"readwrite").put(value))}function add(name,value){return result(store(name,"readwrite").add(value))}function remove(name,key){return result(store(name,"readwrite").delete(key))}
function blobUrl(key,blob){if(!blob)return"";if(!objectUrls.has(key))objectUrls.set(key,URL.createObjectURL(blob));return objectUrls.get(key)}
function urlFor(track,kind){return blobUrl(`${track.id}-${kind}`,track[kind])}function coverStyle(track){const colors=track.colors||palette[track.id%palette.length];return`--cover-a:${colors[0]};--cover-b:${colors[1]}`}function initials(value){return String(value).split(/\s+/).map(w=>w[0]).join("").slice(0,2).toUpperCase()||"CS"}
function currentProfile(){return state.profiles.find(p=>p.id===state.activeProfile)||null}function artistFor(name){return state.artists.find(a=>a.name===name)}function artistBlocked(name){return artistFor(name)?.status==="blocked"}function monthStart(){const d=new Date();return new Date(d.getFullYear(),d.getMonth(),1).getTime()}function likeCount(id,period="alltime"){return state.likes.filter(x=>x.trackId===id&&(period!=="monthly"||x.createdAt>=monthStart())).length}function isLiked(id){return state.likes.some(x=>x.trackId===id&&x.profileId===state.activeProfile)}function isFollowing(artist){return state.follows.some(x=>x.artist===artist&&x.profileId===state.activeProfile)}
function memberStats(profile){const saved={visits:0,seconds:0,plays:0,shares:0,referrals:0,...(profile?.activity||{})};return{...saved,likes:state.likes.filter(x=>x.profileId===profile?.id).length,follows:state.follows.filter(x=>x.profileId===profile?.id).length}}
function fanPoints(profile){const s=memberStats(profile);return s.visits*5+Math.floor(s.seconds/60)+s.plays*2+s.likes*5+s.follows*8+s.shares*10+s.referrals*50}
function fanRank(profile){const points=fanPoints(profile);return[...FAN_RANKS].reverse().find(rank=>points>=rank.min)||FAN_RANKS[0]}
function nextFanRank(profile){const points=fanPoints(profile);return FAN_RANKS.find(rank=>rank.min>points)||null}
function artistStats(name){const ids=new Set(state.tracks.filter(t=>t.artist===name).map(t=>t.id));return{views:state.tracks.filter(t=>t.artist===name).reduce((sum,t)=>sum+(t.views||0),0),likes:state.likes.filter(x=>ids.has(x.trackId)).length,follows:new Set(state.follows.filter(x=>x.artist===name).map(x=>x.profileId)).size}}
function milestoneSetting(){return state.settings.find(x=>x.key==="milestones")||{key:"milestones",items:[]}}
function toast(message){const el=$("#toast");el.textContent=message;el.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove("show"),2300)}

async function refresh(){[state.tracks,state.profiles,state.likes,state.follows,state.artists,state.settings]=await Promise.all([all("tracks"),all("profiles"),all("likes"),all("follows"),all("artists"),all("settings")]);state.tracks.sort((a,b)=>b.createdAt-a.createdAt);state.artists.sort((a,b)=>a.name.localeCompare(b.name));if(state.activeProfile!=="guest"&&(!currentProfile()||currentProfile().status==="blocked")){state.activeProfile="guest";localStorage.setItem("chuneside-active-profile","guest")}renderAll()}
function renderProfiles(){const select=$("#profileSelect");select.innerHTML='<option value="guest">Guest — listen only</option>';state.profiles.filter(p=>p.status!=="blocked").forEach(p=>{const o=document.createElement("option"),rank=fanRank(p);o.value=p.id;o.textContent=`${rank.icon} ${p.name}${p.email?` · ${p.email}`:""}${p.status==="frozen"?" · Frozen":""}`;select.append(o)});select.value=state.activeProfile;renderFanIdentity()}
function renderArtistSelect(selected=""){const select=$("#artistSelect");select.innerHTML='<option value="">Select an artist</option>';state.artists.filter(a=>a.status!=="blocked"||a.name===selected).forEach(a=>{const o=document.createElement("option");o.value=a.name;o.textContent=`${a.name}${a.status==="blocked"?" · Blocked":""}`;select.append(o)});if(selected)select.value=selected}
function renderArtists(){const el=$("#artistList");el.innerHTML=state.artists.length?state.artists.map(a=>{const count=state.tracks.filter(t=>t.artist===a.name).length;return`<div class="artist-chip ${a.status==="blocked"?"blocked":""}"><button class="artist-open" data-id="${esc(a.id)}"><b>${esc(initials(a.name))}</b><span>${esc(a.name)}</span><small>${esc(a.origin)} · ${count} ${count===1?"release":"releases"}</small></button>${a.status==="blocked"?'<span class="status-tag">Blocked</span>':""}<button class="artist-edit" data-id="${esc(a.id)}">Edit</button><button class="delete-artist" data-id="${esc(a.id)}" aria-label="Delete ${esc(a.name)}">×</button></div>`}).join(""):'<div class="empty-state"><b>No artists yet</b><p>Add an artist, then their name will appear in every new-release dropdown.</p></div>';renderArtistSelect()}
function heroItems(setting=state.settings.find(x=>x.key==="heroMedia")){if(!setting)return[];const files=setting.files?.length?setting.files:setting.blob?[{blob:setting.blob,mediaType:setting.mediaType,fileName:setting.fileName}]:[];return files.map((item,index)=>({...item,id:item.id||`legacy-${index}-${item.fileName||"media"}`}))}
function renderHero(){clearInterval(heroTimer);const setting=state.settings.find(x=>x.key==="heroMedia"),stage=$("#heroStage"),video=$("#heroVideo"),image=$("#heroImage"),items=heroItems(setting);stage.classList.remove("fx-glitch","fx-fade","fx-slide","fx-static","slide-change");if(!setting||!items.length){image.hidden=true;image.removeAttribute("src");video.hidden=false;video.src="assets/chuneside-hero-loop.mp4";stage.classList.add("fx-glitch");video.play().catch(()=>{});return}const effect=setting.effect||"glitch";stage.classList.add(`fx-${effect}`);let index=0;const show=()=>{const item=items[index],url=blobUrl(`hero-setting-${item.id}`,item.blob);if(item.mediaType.startsWith("video/")){image.hidden=true;video.hidden=false;video.src=url;video.play().catch(()=>{})}else{video.pause();video.hidden=true;image.hidden=false;image.src=url;if(effect!=="static"){stage.classList.remove("slide-change");void stage.offsetWidth;stage.classList.add("slide-change")}}};show();if(items.length>1)heroTimer=setInterval(()=>{index=(index+1)%items.length;show()},Number(setting.interval)||6000)}
function renderBanner(){clearTimeout(bannerTimer);const setting=state.settings.find(x=>x.key==="banner")||{},banner=$("#scrollingBanner"),text=$("#scrollingBannerText"),messages=(setting.messages?.length?setting.messages:[setting.text?{text:setting.text,duration:10}:null]).filter(x=>x?.text?.trim());if(!setting.enabled||!messages.length){banner.hidden=true;return}const motion=setting.motion||"scroll";banner.hidden=false;banner.className=`scrolling-banner ${setting.position||"bottom"} mode-${motion} font-${setting.fontStyle||"clean"} height-${setting.height||"standard"}`;banner.style.setProperty("--banner-speed",`${Number(setting.scrollSpeed)||40}s`);banner.style.setProperty("--banner-size",`${Number(setting.textSize)||18}px`);banner.style.setProperty("--banner-bg",setting.background||"#dfff00");banner.style.setProperty("--banner-color",setting.textColor||"#08090b");if(motion==="scroll"){const line=messages.map(x=>x.text.trim()).join("   ◆   ");text.textContent=`${line}   ◆   ${line}`;return}let index=0;const show=()=>{const message=messages[index],duration=Math.max(1,Math.min(300,Number(message.duration)||10));text.textContent=message.text;text.style.setProperty("--message-duration",`${duration}s`);text.classList.remove("message-active");void text.offsetWidth;text.classList.add("message-active");bannerTimer=setTimeout(()=>{index=(index+1)%messages.length;show()},duration*1000)};show()}
function renderSubmission(){const setting={...DEFAULT_SUBMISSION,...(state.settings.find(x=>x.key==="submission")||{})},items=[["01","Audio",setting.audio],["02","Video",setting.video],["03","Album artwork",setting.artwork],["04","Artist picture",setting.artistPicture]];$("#submissionRequirements").innerHTML=items.map(([n,title,copy])=>`<article class="requirement-card"><span>${n}</span><h3>${esc(title)}</h3><p>${esc(copy)}</p></article>`).join("");$("#submissionEmails").textContent=setting.emails;const first=setting.emails.split(",")[0].trim();$("#submissionEmailLink").href=`mailto:${encodeURIComponent(first)}`}
function renderMembers(){const el=$("#memberAdminList");el.innerHTML=state.profiles.length?state.profiles.map(p=>{const s=memberStats(p),rank=fanRank(p),points=fanPoints(p);return`<article class="management-row ${esc(p.status||"active")}"><div><strong><span class="rank-emblem">${rank.icon}</span> ${esc(p.name)} · ${esc(rank.name)}</strong><span>${esc(p.email||"No email — local test profile")}</span><small>${p.provider==="google-demo"?"Google demo":p.provider==="email"?"Email membership":"Test profile"} · Joined ${new Date(p.createdAt).toLocaleDateString()} · ${points} points</small><small>${s.visits} visits · ${Math.floor(s.seconds/60)} active min · ${s.plays} plays · ${s.likes} Likes · ${s.follows} Follows · ${s.shares} Shares</small></div><div class="member-status">${esc(p.status||"active")}</div><div class="management-actions"><button class="edit-member" data-id="${esc(p.id)}">Edit</button><button class="freeze-member" data-id="${esc(p.id)}">${p.status==="frozen"?"Unfreeze":"Freeze"}</button><button class="block-member" data-id="${esc(p.id)}">${p.status==="blocked"?"Unblock":"Block"}</button><button class="remove-member" data-id="${esc(p.id)}">Delete</button></div></article>`}).join(""):'<div class="empty-state"><b>No members yet</b></div>';bindMemberActions()}
function publicTracks(){return state.tracks.filter(t=>!artistBlocked(t.artist))}
function renderRegions(){const tracks=publicTracks(),regions=[["all","All"],["wadadli","Wadadli"],["caribbean","Caribbean"],["world","World"],["ai","AI-assisted"]];$("#filters").innerHTML=regions.map(([key,label])=>{const count=key==="all"?tracks.length:tracks.filter(t=>t.origin===key).length;return`<button class="count-filter ${state.filter===key?"active":""}" data-filter="${key}"><span>${label}</span><small>${count}</small></button>`}).join("")}
function renderGenres(){const label=state.filter==="all"?"All regions":state.filter==="ai"?"AI-assisted":state.filter[0].toUpperCase()+state.filter.slice(1),tracks=publicTracks().filter(t=>state.filter==="all"||t.origin===state.filter);$("#genreMenuLabel").textContent=`${label} · Genres`;$("#genreFilters").innerHTML=GENRES.map(g=>{const count=g==="All genres"?tracks.length:g==="Other"?tracks.filter(t=>!GENRES.slice(1,-1).includes(t.genre)).length:tracks.filter(t=>t.genre===g).length;return`<button class="count-filter ${state.genre===g?"active":""}" data-genre="${esc(g)}"><span>${esc(g)}</span><small>${count}</small></button>`}).join("")}
function trackCard(track){const cover=urlFor(track,"cover"),likes=likeCount(track.id),artist=artistFor(track.artist);return`<article class="track-card"><button class="cover-button play-release" data-id="${track.id}" style="${coverStyle(track)}" aria-label="Play ${esc(track.title)}">${cover?`<img src="${cover}" alt="">`:""}<span class="type-badge">${esc(track.creation)} · ${esc(track.type)}</span><span class="cover-mark">${esc(initials(track.artist))}</span><span class="play-or-video">${track.type==="video"?"▶":"♪"}</span></button><div class="track-info"><div><h3>${esc(track.title)}</h3><p>${artist?`<button class="artist-name-link artist-open" data-id="${esc(artist.id)}">${esc(track.artist)}</button>`:esc(track.artist)} · ${esc(track.genre||"Other")}</p><small>${esc(track.origin)} · ${(track.views||0).toLocaleString()} views</small></div><small>${track.type==="video"?"VIDEO":"AUDIO"}</small></div><div class="track-actions"><button class="like-button ${isLiked(track.id)?"active":""}" data-id="${track.id}">♥ ${likes} ${likes===1?"Like":"Likes"}</button><button class="share-button" data-id="${track.id}">↗ Share</button><button class="follow follow-button ${isFollowing(track.artist)?"active":""}" data-id="${track.id}">＋ ${isFollowing(track.artist)?"Following":"Follow"}</button></div></article>`}
function renderTracks(){const shown=state.tracks.filter(t=>!artistBlocked(t.artist)&&(state.filter==="all"||t.origin===state.filter)&&(state.genre==="All genres"||(state.genre==="Other"?!GENRES.slice(1,-1).includes(t.genre):t.genre===state.genre))&&`${t.title} ${t.artist} ${t.genre}`.toLowerCase().includes(state.query));shown.sort((a,b)=>state.sort==="oldest"?a.createdAt-b.createdAt:state.sort==="views"?(b.views||0)-(a.views||0)||b.createdAt-a.createdAt:state.sort==="likes"?likeCount(b.id)-likeCount(a.id)||b.createdAt-a.createdAt:state.sort==="az"?a.title.localeCompare(b.title):b.createdAt-a.createdAt);$("#trackGrid").innerHTML=shown.length?shown.map(trackCard).join(""):`<div class="empty-state"><b>${state.tracks.length?"No matching releases":"Your stage is ready"}</b><p>${state.tracks.length?"Try another region, genre or search.":"Add a song or music video to begin testing ChuneSide."}</p><button class="primary-button open-add">＋ Add release</button></div>`}
function renderVideos(){const videos=state.tracks.filter(t=>t.type==="video"&&!artistBlocked(t.artist));$("#videoGrid").innerHTML=videos.length?videos.map(t=>{const cover=urlFor(t,"cover"),media=urlFor(t,"media");return`<button class="video-card play-release" data-id="${t.id}" style="${coverStyle(t)}">${cover?`<img src="${cover}" alt="">`:`<video src="${media}" muted preload="metadata"></video>`}<div><span>${esc(t.origin)} · ${esc(t.genre)}</span><strong>${esc(t.title)}</strong><p>${esc(t.artist)}</p></div><i>▶</i></button>`}).join(""):`<div class="empty-state"><b>No test videos yet</b><p>Add an MP4 or WebM video to test the video wall.</p><button class="primary-button open-add" data-type="video">＋ Add video</button></div>`}
function renderCharts(){const select=$("#chartGenre");if(!select.options.length)select.innerHTML=GENRES.map(g=>`<option>${esc(g)}</option>`).join("");select.value=state.chartGenre;const ranked=state.tracks.filter(track=>!artistBlocked(track.artist)&&(state.chartGenre==="All genres"||(state.chartGenre==="Other"?!GENRES.slice(1,-1).includes(track.genre):track.genre===state.chartGenre))).map(track=>({track,count:likeCount(track.id,state.period)})).filter(x=>x.count>0).sort((a,b)=>b.count-a.count||(b.track.views||0)-(a.track.views||0));$("#leaderboard").innerHTML=ranked.length?ranked.map(({track,count},i)=>`<article class="rank-row"><span class="rank-no">${String(i+1).padStart(2,"0")}</span><div class="rank-art" style="${coverStyle(track)}">${esc(initials(track.artist))}</div><div class="rank-meta"><strong>${esc(track.title)}</strong><span>${esc(track.artist)} · ${esc(track.genre)} · ${(track.views||0).toLocaleString()} views</span></div><div class="rank-likes"><span>♥</span><b>${count}</b><small>unique ${count===1?"like":"likes"}</small></div><button class="play-release" data-id="${track.id}">▶</button></article>`).join(""):`<div class="empty-state"><b>No ${state.chartGenre==="All genres"?"":"rated "+state.chartGenre+" "}songs in this chart yet</b><p>Choose another genre or add member Likes to this selection.</p></div>`}
function renderAdmin(){const el=$("#adminList");el.innerHTML=state.tracks.length?state.tracks.map(t=>`<article class="admin-row"><div class="admin-thumb" style="${coverStyle(t)}">${esc(initials(t.artist))}</div><div><strong>${esc(t.title)}</strong><p>${esc(t.artist)} · ${esc(t.genre)} · ${esc(t.origin)}</p></div><div class="admin-actions"><button class="edit-release" data-id="${t.id}">Edit</button><button class="delete-release" data-id="${t.id}">Delete</button></div></article>`).join(""):'<div class="empty-state"><b>No releases loaded</b><p>Your uploaded test media will appear here.</p></div>';if(navigator.storage?.estimate)navigator.storage.estimate().then(({usage=0,quota=0})=>$("#storageText").textContent=`Using ${(usage/1048576).toFixed(1)} MB of approximately ${(quota/1048576).toFixed(0)} MB available in this browser.`)}
function applyTheme(){const owner=state.settings.find(x=>x.key==="theme")||{...THEMES.original,allowVisitorThemes:false},choice=localStorage.getItem("chuneside-visitor-theme")||"owner",theme=owner.allowVisitorThemes&&choice!=="owner"&&THEMES[choice]?THEMES[choice]:owner;document.documentElement.style.setProperty("--acid",theme.primary);document.documentElement.style.setProperty("--violet",theme.secondary);document.documentElement.style.setProperty("--pink",theme.accent);document.documentElement.style.setProperty("--bg",theme.bg||"#07080a");document.documentElement.style.setProperty("--panel",theme.panel||"#111319");$("#openVisitorTheme").hidden=!owner.allowVisitorThemes}
function brandingSetting(){return{eyebrow:"OFFLINE TEST EDITION · VERSION 1.2.5",titleOne:"Your music.",titleTwo:"Your test lab.",description:"Add your own songs, videos and artwork. Everything stays on this computer.",buttonText:"＋ Add your first release",logoPosition:"left",logoSize:"medium",...(state.settings.find(x=>x.key==="branding")||{})}}
function renderBranding(){const setting=brandingSetting(),logo=$(".brand img"),topbar=$(".topbar");$("#heroEyebrow").textContent=setting.eyebrow;$("#heroTitleOne").textContent=setting.titleOne;$("#heroTitleTwo").textContent=setting.titleTwo;$("#heroDescription").textContent=setting.description;$("#heroButtonText").textContent=setting.buttonText;logo.src=setting.logo?blobUrl("branding-logo",setting.logo):"assets/chuneside-logo.png";topbar.classList.remove("logo-left","logo-center","logo-right","logo-small","logo-medium","logo-large");topbar.classList.add(`logo-${setting.logoPosition}`,`logo-${setting.logoSize}`)}
function renderFanIdentity(){const badge=$("#memberRankBadge"),summary=$("#myRankSummary"),profile=currentProfile();if(!profile){badge.hidden=true;if(summary)summary.innerHTML='<span>Sign in to build your fan rank</span>';return}const rank=fanRank(profile),next=nextFanRank(profile),points=fanPoints(profile),progress=next?Math.min(100,Math.round((points-rank.min)/(next.min-rank.min)*100)):100;badge.hidden=false;badge.innerHTML=`<b>${rank.icon}</b><span>${esc(rank.name)}</span>`;badge.title=`${points} activity points`;if(summary)summary.innerHTML=`<div class="rank-symbol">${rank.icon}</div><div><small>Your fan rank</small><strong>${esc(rank.name)}</strong><span>${points} points${next?` · ${next.min-points} to ${esc(next.name)}`:" · Highest rank"}</span><i><u style="width:${progress}%"></u></i></div>`}
function renderActivity(){renderFanIdentity();const items=[...(milestoneSetting().items||[])].sort((a,b)=>b.createdAt-a.createdAt),feed=$("#milestoneFeed");feed.innerHTML=items.length?items.slice(0,60).map(item=>`<article class="milestone-item"><b>${item.icon||"✦"}</b><div><strong>${esc(item.message)}</strong><span>${new Date(item.createdAt).toLocaleString()}</span></div></article>`).join(""):'<div class="empty-state"><b>No milestones yet</b><p>Artist achievements will appear here automatically as people listen, Like and Follow.</p></div>';const ranked=state.profiles.filter(p=>p.status!=="blocked").sort((a,b)=>fanPoints(b)-fanPoints(a));$("#fanLeaderboard").innerHTML=ranked.length?ranked.map((p,i)=>{const rank=fanRank(p),s=memberStats(p);return`<article class="fan-row"><span>${String(i+1).padStart(2,"0")}</span><b class="rank-symbol">${rank.icon}</b><div><strong>${esc(p.name)}</strong><small>${esc(rank.name)} · ${fanPoints(p)} points · Member since ${new Date(p.createdAt).toLocaleDateString()}</small><small>${s.visits} visits · ${Math.floor(s.seconds/60)} min · ${s.plays} plays · ${s.likes+s.follows+s.shares} actions</small></div></article>`}).join(""):'<div class="empty-state"><b>No members yet</b></div>';$("#rankGuide").innerHTML=FAN_RANKS.map(rank=>`<article><b>${rank.icon}</b><span><strong>${esc(rank.name)}</strong><small>${rank.min.toLocaleString()}+ points</small></span></article>`).join("")}
function renderAll(){applyTheme();renderBranding();renderProfiles();renderRegions();renderGenres();renderTracks();renderVideos();renderCharts();renderActivity();renderAdmin();renderArtists();renderHero();renderBanner();renderSubmission();if($("#membersDialog").open)renderMembers();bindDynamic()}
