async function recordMemberMetric(metric,amount=1){const profile=currentProfile();if(!profile||profile.status==="blocked")return;const activity={visits:0,seconds:0,plays:0,shares:0,referrals:0,...(profile.activity||{})};activity[metric]=(activity[metric]||0)+amount;activity.lastActiveAt=Date.now();profile.activity=activity;await put("profiles",profile);renderFanIdentity();if($("#membersDialog").open)renderMembers()}
