async function shareRelease(id){const track=state.tracks.find(x=>x.id===id);if(!track)return;const text=`Listen to ${track.title} by ${track.artist} on ChuneSide.`;try{if(navigator.share)await navigator.share({title:`${track.title} · ChuneSide`,text});else if(navigator.clipboard)await navigator.clipboard.writeText(text);else{const area=document.createElement("textarea");area.value=text;document.body.append(area);area.select();document.execCommand("copy");area.remove()}await recordMemberMetric("shares");toast(currentProfile()?"Shared — your fan activity increased.":"Share message copied.")}catch(error){if(error?.name!=="AbortError")toast("Sharing is not available in this browser.")}}
