async function saveMember(event){event.preventDefault();const name=String(new FormData(event.currentTarget).get("name")).trim();if(!name)return;await flushActivityTime();const id=crypto.randomUUID?.()||`member-${Date.now()}`;await put("profiles",{id,name,createdAt:Date.now()});state.activeProfile=id;localStorage.setItem("chuneside-active-profile",id);lastActivityTick=Date.now();$("#memberDialog").close();await refresh();await recordMemberMetric("visits");toast(`${name} is ready to test.`)}
