function openTheme(){const theme=state.settings.find(x=>x.key==="theme")||THEMES.original,form=$("#themeForm");form.elements.namedItem("primary").value=theme.primary;form.elements.namedItem("secondary").value=theme.secondary;form.elements.namedItem("accent").value=theme.accent;form.elements.namedItem("allowVisitorThemes").checked=Boolean(theme.allowVisitorThemes);$("#themeDialog").showModal()}
async function submitTheme(event){event.preventDefault();const data=new FormData(event.currentTarget);await saveTheme({primary:String(data.get("primary")),secondary:String(data.get("secondary")),accent:String(data.get("accent"))},data.get("allowVisitorThemes")==="on");$("#themeDialog").close()}
function bindMemberActions(){$$(".edit-member").forEach(b=>b.onclick=()=>openMemberEditor(b.dataset.id));$$(".freeze-member").forEach(b=>b.onclick=()=>setMemberStatus(b.dataset.id,state.profiles.find(p=>p.id===b.dataset.id)?.status==="frozen"?"active":"frozen"));$$(".block-member").forEach(b=>b.onclick=()=>setMemberStatus(b.dataset.id,state.profiles.find(p=>p.id===b.dataset.id)?.status==="blocked"?"active":"blocked"));$$(".remove-member").forEach(b=>b.onclick=()=>deleteMember(b.dataset.id))}
function openMemberEditor(id){const profile=state.profiles.find(p=>p.id===id);if(!profile)return;const form=$("#memberEditForm");form.reset();form.elements.namedItem("id").value=profile.id;form.elements.namedItem("name").value=profile.name;form.elements.namedItem("email").value=profile.email||"";form.elements.namedItem("status").value=profile.status||"active";$("#memberEditDialog").showModal()}
async function saveMemberEdit(event){event.preventDefault();const data=new FormData(event.currentTarget),id=String(data.get("id")),profile=state.profiles.find(p=>p.id===id),email=String(data.get("email")||"").trim().toLowerCase(),newPassword=String(data.get("newPassword")||"");if(!profile)return;if(email&&state.profiles.some(p=>p.id!==id&&p.email===email))return toast("That email belongs to another member.");const updated={...profile,name:String(data.get("name")).trim(),email,status:String(data.get("status"))};if(newPassword){updated.salt=crypto.randomUUID?.()||String(Math.random());updated.passwordHash=await hashPassword(newPassword,updated.salt);updated.provider="email"}await put("profiles",updated);$("#memberEditDialog").close();await refresh();renderMembers();toast(newPassword?"Member details and password reset saved.":"Member details updated.")}
async function setMemberStatus(id,status){const profile=state.profiles.find(p=>p.id===id);if(!profile)return;if((status==="blocked"||status==="frozen")&&!confirm(`${status==="blocked"?"Block":"Freeze"} ${profile.name}?`))return;await put("profiles",{...profile,status});await refresh();renderMembers();toast(`${profile.name} is now ${status}.`)}
async function deleteMember(id){const profile=state.profiles.find(p=>p.id===id);if(!profile||!confirm(`Delete ${profile.name} and remove their Likes and Follows?`))return;for(const like of state.likes.filter(x=>x.profileId===id))await remove("likes",like.key);for(const follow of state.follows.filter(x=>x.profileId===id))await remove("follows",follow.key);await remove("profiles",id);if(state.activeProfile===id){state.activeProfile="guest";localStorage.setItem("chuneside-active-profile","guest")}await refresh();renderMembers();toast("Member deleted.")}
function openSubmissionSettings(){const setting={...DEFAULT_SUBMISSION,...(state.settings.find(x=>x.key==="submission")||{})},form=$("#submissionSettingsForm");for(const field of ["emails","audio","video","artwork","artistPicture"])form.elements.namedItem(field).value=setting[field];$("#submissionSettingsDialog").showModal()}
async function saveSubmissionSettings(event){event.preventDefault();const data=new FormData(event.currentTarget);await put("settings",{key:"submission",emails:String(data.get("emails")).trim(),audio:String(data.get("audio")).trim(),video:String(data.get("video")).trim(),artwork:String(data.get("artwork")).trim(),artistPicture:String(data.get("artistPicture")).trim(),updatedAt:Date.now()});$("#submissionSettingsDialog").close();await refresh();toast("Submission instructions updated.")}
function openBanner(){const setting=state.settings.find(x=>x.key==="banner")||{},form=$("#bannerForm"),messages=setting.messages?.length?setting.messages:setting.text?[{text:setting.text,duration:10}]:[];form.reset();form.elements.namedItem("enabled").checked=Boolean(setting.enabled);for(const field of ["position","motion","textSize","fontStyle","scrollSpeed","height"])form.elements.namedItem(field).value=String(setting[field]||({position:"bottom",motion:"scroll",textSize:18,fontStyle:"clean",scrollSpeed:40,height:"standard"})[field]);form.elements.namedItem("background").value=setting.background||"#dfff00";form.elements.namedItem("textColor").value=setting.textColor||"#08090b";for(let i=1;i<=6;i++){form.elements.namedItem(`message${i}`).value=messages[i-1]?.text||"";form.elements.namedItem(`duration${i}`).value=messages[i-1]?.duration||[5,10,15,30,60,60][i-1]}$("#bannerDialog").showModal()}
async function saveBanner(event){event.preventDefault();const data=new FormData(event.currentTarget),messages=[];for(let i=1;i<=6;i++){const text=String(data.get(`message${i}`)||"").trim();if(text)messages.push({text,duration:Math.max(1,Math.min(300,Number(data.get(`duration${i}`))||10))})}if(data.get("enabled")==="on"&&!messages.length)return toast("Add at least one announcement message.");await put("settings",{key:"banner",enabled:data.get("enabled")==="on",messages,position:String(data.get("position")||"bottom"),motion:String(data.get("motion")||"scroll"),textSize:Number(data.get("textSize"))||18,fontStyle:String(data.get("fontStyle")||"clean"),scrollSpeed:Number(data.get("scrollSpeed"))||40,height:String(data.get("height")||"standard"),background:String(data.get("background")||"#dfff00"),textColor:String(data.get("textColor")||"#08090b"),updatedAt:Date.now()});$("#bannerDialog").close();await refresh();toast("Homepage message display updated.")}
function openBranding(){const setting=brandingSetting(),form=$("#brandingForm");form.reset();for(const field of ["eyebrow","titleOne","titleTwo","description","buttonText","logoPosition","logoSize"])form.elements.namedItem(field).value=setting[field];$("#brandingDialog").showModal()}
async function saveBranding(event){event.preventDefault();const data=new FormData(event.currentTarget),existing=state.settings.find(x=>x.key==="branding")||{},logo=data.get("logo"),hasLogo=logo instanceof File&&logo.size;if(hasLogo&&logo.size>20*1024*1024&&!confirm("This logo is larger than 20 MB. Save it anyway?"))return;if(hasLogo&&objectUrls.has("branding-logo")){URL.revokeObjectURL(objectUrls.get("branding-logo"));objectUrls.delete("branding-logo")}await put("settings",{...existing,key:"branding",eyebrow:String(data.get("eyebrow")).trim(),titleOne:String(data.get("titleOne")).trim(),titleTwo:String(data.get("titleTwo")).trim(),description:String(data.get("description")).trim(),buttonText:String(data.get("buttonText")).trim(),logo:hasLogo?logo:existing.logo||null,logoPosition:String(data.get("logoPosition")||"left"),logoSize:String(data.get("logoSize")||"medium"),updatedAt:Date.now()});$("#brandingDialog").close();await refresh();toast("Hero wording and branding updated.")}
async function restoreSuppliedLogo(){const existing=state.settings.find(x=>x.key==="branding");if(!existing)return toast("The supplied ChuneSide logo is already active.");if(!confirm("Restore the supplied ChuneSide logo? Your hero wording will stay unchanged."))return;if(objectUrls.has("branding-logo")){URL.revokeObjectURL(objectUrls.get("branding-logo"));objectUrls.delete("branding-logo")}await put("settings",{...existing,logo:null,updatedAt:Date.now()});await refresh();toast("Supplied ChuneSide logo restored.")}
async function clearAll(){if(!confirm("Delete every uploaded song, video, artist, hero, test member, Like and Follow?"))return;state.db.close();await new Promise((resolve,reject)=>{const request=indexedDB.deleteDatabase(DB_NAME);request.onsuccess=resolve;request.onerror=()=>reject(request.error);request.onblocked=()=>toast("Close other ChuneSide tabs, then try again.")});localStorage.removeItem("chuneside-active-profile");location.reload()}

async function init(){state.db=await openDb();const profiles=await all("profiles");if(!profiles.length)await put("profiles",{id:"owner-test",name:"Nigel · Test member",createdAt:Date.now()});const [tracks,artists]=await Promise.all([all("tracks"),all("artists")]);if(!artists.length&&tracks.length){const names=[...new Map(tracks.map(t=>[t.artist.toLowerCase(),t])).values()];for(const t of names)await put("artists",{id:crypto.randomUUID?.()||`artist-${Date.now()}-${Math.random()}`,name:t.artist,origin:t.origin,createdAt:Date.now()})}if(state.activeProfile==="guest")state.activeProfile="owner-test";await refresh();await recordMemberMetric("visits");startActivityTracking();$$('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$("#profileSelect").onchange=async e=>{await flushActivityTime();state.activeProfile=e.target.value;localStorage.setItem("chuneside-active-profile",state.activeProfile);lastActivityTick=Date.now();renderAll();if(state.activeProfile!=="guest")await recordMemberMetric("visits");toast(state.activeProfile==="guest"?"Guest mode: listening only.":`Testing as ${currentProfile().name}.`)};$("#searchInput").oninput=e=>{state.query=e.target.value.trim().toLowerCase();renderTracks();bindDynamic()};$$("#filters button").forEach(b=>b.onclick=()=>{$$("#filters button").forEach(x=>x.classList.remove("active"));b.classList.add("active");state.filter=b.dataset.filter;state.genre="All genres";renderGenres();renderTracks();bindDynamic()});$$(".period-switch button").forEach(b=>b.onclick=()=>{$$(".period-switch button").forEach(x=>x.classList.remove("active"));b.classList.add("active");state.period=b.dataset.period;renderCharts();bindDynamic()});$("#releaseForm").onsubmit=saveRelease;$("#memberForm").onsubmit=saveMember;$("#artistForm").onsubmit=saveArtist;$("#heroForm").onsubmit=saveHero;$("#signupForm").onsubmit=saveSignup;$("#signinForm").onsubmit=saveSignin;$("#themeForm").onsubmit=submitTheme;$("#heroAdd").onclick=()=>openRelease();$("#addMemberStudio").onclick=()=>$("#memberDialog").showModal();$("#openSignup").onclick=()=>openSignup();$("#googleSignup").onclick=googleSignup;$("#addArtistStudio").onclick=$("#quickAddArtist").onclick=()=>openArtistEditor();$("#catalogEditArtist").onclick=e=>{$("#artistCatalogDialog").close();openArtistEditor(e.currentTarget.dataset.id)};$("#changeHero").onclick=()=>{$("#heroForm").reset();$("#heroDialog").showModal()};$("#resetHero").onclick=resetHero;$("#openTheme").onclick=openTheme;$$('[data-theme]').forEach(b=>b.onclick=async()=>{await saveTheme(THEMES[b.dataset.theme]);$("#themeDialog").close()});$$('[data-auth-tab]').forEach(b=>b.onclick=()=>setAuthTab(b.dataset.authTab));$("#guestCreate").onclick=()=>{$("#guestDialog").close();openSignup()};$$(".close-modal").forEach(b=>b.onclick=()=>$("#addDialog").close());$$(".close-member").forEach(b=>b.onclick=()=>$("#memberDialog").close());$$(".close-artist").forEach(b=>b.onclick=()=>$("#artistDialog").close());$$(".close-catalog").forEach(b=>b.onclick=()=>$("#artistCatalogDialog").close());$$(".close-hero").forEach(b=>b.onclick=()=>$("#heroDialog").close());$$(".close-theme").forEach(b=>b.onclick=()=>$("#themeDialog").close());$$(".close-signup").forEach(b=>b.onclick=()=>$("#signupDialog").close());$$(".close-guest").forEach(b=>b.onclick=()=>$("#guestDialog").close());$("#closeVideo").onclick=()=>{$("#videoPlayer").pause();$("#videoDialog").close()};$("#closePlayer").onclick=()=>{$("#audioPlayer").pause();$("#playerBar").classList.add("hidden")};$("#mediaType").onchange=e=>$("#mediaFile").accept=e.target.value==="video"?"video/*":"audio/*";$("#genreSelect").onchange=e=>{$("#otherGenreLabel").hidden=e.target.value!=="Other";$("#otherGenre").required=e.target.value==="Other"};$("#clearData").onclick=clearAll;if("serviceWorker"in navigator&&location.protocol.startsWith("http"))navigator.serviceWorker.register("sw.js").catch(()=>{})}
function bindV121(){$("#openMembers").onclick=()=>{renderMembers();$("#membersDialog").showModal()};$("#memberEditForm").onsubmit=saveMemberEdit;$("#openSubmissionSettings").onclick=openSubmissionSettings;$("#submissionSettingsForm").onsubmit=saveSubmissionSettings;$("#openBanner").onclick=openBanner;$("#bannerForm").onsubmit=saveBanner;$("#catalogBlockArtist").onclick=e=>toggleArtistBlock(e.currentTarget.dataset.id);$$(".close-members").forEach(b=>b.onclick=()=>$("#membersDialog").close());$$(".close-member-edit").forEach(b=>b.onclick=()=>$("#memberEditDialog").close());$$(".close-submission-settings").forEach(b=>b.onclick=()=>$("#submissionSettingsDialog").close());$$(".close-banner").forEach(b=>b.onclick=()=>$("#bannerDialog").close())}
function bindV122(){$("#openVisitorTheme").onclick=()=>$("#visitorThemeDialog").showModal();$$(".close-visitor-theme").forEach(b=>b.onclick=()=>$("#visitorThemeDialog").close());$$('[data-visitor-theme]').forEach(b=>b.onclick=()=>{localStorage.setItem("chuneside-visitor-theme",b.dataset.visitorTheme);applyTheme();$("#visitorThemeDialog").close();toast(b.dataset.visitorTheme==="owner"?"Using the ChuneSide default theme.":"Your display theme has been changed.")});$$('[data-theme]').forEach(b=>b.onclick=async()=>{const allow=$("#themeForm").elements.namedItem("allowVisitorThemes").checked;await saveTheme(THEMES[b.dataset.theme],allow);$("#themeDialog").close()})}
function bindV123(){$("#changeHero").onclick=openHeroManager}
function bindV124(){$("#trackSort").onchange=e=>{state.sort=e.target.value;renderTracks();bindDynamic()};$("#chartGenre").onchange=e=>{state.chartGenre=e.target.value;renderCharts();bindDynamic()};$("#openBranding").onclick=openBranding;$("#brandingForm").onsubmit=saveBranding;$("#restoreLogo").onclick=restoreSuppliedLogo;$$(".close-branding").forEach(b=>b.onclick=()=>$("#brandingDialog").close());bindDynamic()}
function bindV125(){$("#openRanks").onclick=()=>{$("#ranksDialog").showModal();renderActivity()};$$(".close-ranks").forEach(b=>b.onclick=()=>$("#ranksDialog").close())}
init().then(()=>{bindV121();bindV122();bindV123();bindV124();bindV125()}).catch(error=>{console.error(error);toast("ChuneSide could not open local storage. Try the launcher again.")});
